    eta: { sql: 'x.eta', type: 'date', label: 'Expected at site' }, daysLate: { sql: 'x.days_late', type: 'number', label: 'Days late' }, risk: { sql: "CASE WHEN x.at_risk = 1 THEN 'YES' ELSE 'NO' END", type: 'enum', label: 'At risk', options: [['YES', 'Yes'], ['NO', 'No']] },
